"""Stage 3 merge for report 31."""
import json
C = {x["id"]: x for x in json.load(open("Tools/prd_ledger/canonical.json"))}
def ext(cid, text):
    if text not in C[cid]["statement"]: C[cid]["statement"] += text
def add(cid, section, title, statement):
    if cid in C: return
    C[cid] = dict(id=cid, title=title, statement=statement, section=section, cards=[], reports=[], merged_from=[])

add("C247","dont","Never make a sibling-app bundle the only way to buy this app's own premium","Report 31: from mid-2021 the Growth Bundle (Tally, Do, Grateful, Moody, Last, Time Block, Reflectly) was the only upgrade path — 36 reviews (0.69%, mean 2.03): 'There is no way to only upgrade this app to premium'; 'the renewal jumps up to 10x the price in a year's time'; buyers of a $19.99 'lifetime' were routed into a 'gift' bundle upsell, and dismissing it dropped them back to Basic. A bundle can be offered alongside, never instead of, a single-app purchase.")
add("C248","product-rule","Never show an upsell to anyone holding an active or historical entitlement","Report 31: 314 reviews (6.05%, mean 1.57) were upsold after paying — 197 of 625 explicit payers (31.5%) — rising 0.3% (E1) → 12.1% (E4): 'It's not encouraging customer loyalty!!'; mood-disorder tracking interrupted by the offer; a banner in Dec 2020 hid the bottom habit even for paid users. The report's first upsell rule: suppress every offer for any past or present entitlement, and test every-launch vs weekly vs never-for-past-payers on conversion, D30 retention and 1★ rate.")

ext("C001", " Report 31: over ten years one listing moved a £2.99 one-time Pro (2016) → $19.99/yr (31 Aug 2020) → $39.99/yr → bundle-only $59.99–$99.99/yr → a $19.99 'lifetime' against $399–CA$499.99 anchors → ~$60/yr annual only; Touch ID was moved behind the paywall in 2019; the effective entry price rose ~15× in recurring terms and mean rating fell 3.94 → 2.75 in the step that coincided with the subscription switch and ownership change (−1.19).")
ext("C002", " Report 31: every one of the fifteen worst-rated themes is money-handling, support or the app failing to run — no feature gap appears; the free cap (2.01) is far milder than purchase integrity (1.14–1.39): people tolerate a gate, they do not tolerate paying for a gate that doesn't open; the product concept is not what failed — simplicity, colour, sounds and streaks are quoted in the 1★ band as reasons the app is worth using.")
ext("C003", " Report 31: 27 E1 reviewers (mean 4.78) chose Done because it wasn't a subscription ('happily paid the one-time fee because many other programs are switching to a subscription'), 13 later reviews leave for Streaks because it still is one-time, and one-time pricing praise went 2.9% (E1) → 0 in every later era; the report recommends offering a genuine one-time lifetime price alongside monthly and annual and testing all three on conversion and 1★ rate.")
ext("C004", " Report 31: 119 price-praise reviews (mean 3.82), 63 of them E1 (6.7% of the era): 'I'm only paying to support the developers'; 'a one-time charge is a lot less exploitative, and doesn't come with the same guilt'; 'Best $8.99 spent in a long time!' — price praise fell 6.7% → 0.7–1.7% after the subscription.")
ext("C005", " Report 31: competitor mentions flipped direction after 2020 — E1 arrivals (89, 9.5% of E1) from Productive ('$5/month??? Have they lost their minds???'), Streaks, Habitify, Habit-Bull / Way of Life, Strides; E2–E5 departures to Streaks, Habit, Way of Life, DayStamp, Onrise, Habitify, Grit, Finch, Daylio, Structured.")
ext("C006", " Report 31: simple, uncluttered, fast to log is the top praise in every era (458 rated 4–5★; 36.7% of 5★; 'The user discovers value rather than have thousands of distractions flung at him'), and also the top argument against the subscription ('a simple app shouldn't cost…', 104 simplicity mentions are 1★).")
ext("C007", " Report 31: a 3-habit cap (2 in 2016) drew 670 complaints (12.92%, mean 2.01) at 8–18% in every era, 13.5% in E1 and 14.0% in E4 — unchanged — while the price objection moved 4.1% → 13.0% with the subscription; the plurality objection since 2016 is evaluation ('With only 2 items makes it hard to get a feel'; 'I would like to start by tracking 5 habits, not 3'); a minority defend it ('if you've read The One Thing, three is already a lot!'); the report proposes testing 3 vs 5–6 habits vs a 14-day full trial; Spain shows the highest cap rate anywhere (28.6%).")
ext("C011", " Report 31: charts once unlocked are a named purchase trigger ('excited to see them … upgraded immediately'); stats 145 mentions, called weak by power users who want all-habit overviews, weekly totals and % of days.")
ext("C014", " Report 31: multiple reminders per habit were paid in the one-time era and are among what buyers value after paying.")
ext("C015", " Report 31: social / shared lists / family to-do requested by 49 (mean 3.27); a parent tracking attention to each child.")
ext("C016", " Report 31: every-N-days, bi-weekly, skip, vacation mode and end dates requested by 84 (mean 3.12) — 'lose a 100+ day streak because … vacation'; a streak freeze is named as the missing piece between 4★ and 5★.")
ext("C017", " Report 31: a passcode / Touch ID lock was moved behind the paywall in 2019; privacy / passcode 16 mentions.")
ext("C019", " Report 31: build and quit habits in one list is praised by 96 ('the ONLY app I've found that does that'); quit-to-zero goals were removed in Mar 2022 and Jan 2023 (sobriety tracking), and 30 find quit/zero-goal habits confusing — restore them.")
ext("C020", " Report 31: backup to Dropbox/iCloud and CSV export were manual only with a repeated backup nag; export hangs ('I can't export my data to move to another app because it hangs on the CSV export') — export is the exit door, keep it open and fast; export to Google Drive was a purchase trigger.")
ext("C021", " Report 31: Apple Health integration covers ~10 preset tasks (steps, sleep, exercise minutes); 79 mentions (mean 2.85); Health sync named as the missing piece between 4★ and 5★.")
ext("C022", " Report 31: the Watch app and complication were broken for long periods — 60 reviews (mean 2.33); support asked for a video, then silence; ''update coming soon'. 6 months later'; the v2 rebuild (Mar 2022) broke it and restored it months later.")
ext("C023", " Report 31: a tappable Today-view widget (2018–2021) was replaced in Oct 2021 by a non-interactive home/lock-screen widget limited to 4 habits (a user with a memory disability 'requesting a refund'); before that, the app had no iOS 14 widget for a year — 73 of 451 reviews (16.2%) Sep 2020 – Sep 2021 and 14.0% of E2 asked about it; the widget peaks in the 4★ band (12.6% vs 3.8%).")
ext("C024", " Report 31: motivation through bars filling, streaks and sounds is praised by 200 rated 4–5★ ('an adult sticker chart!'); removing the streak count from the main list in v3.0 drew 52 complaints (100% E4), including medication and 30-day pill-cycle users; the report proposes a streak-on-list toggle and testing its default on logging frequency.")
ext("C025", " Report 31: ~110 teen and low-income reviewers (2.12%, mean 2.31) in the 2022–23 TikTok cohort ('your target market at this point is us teenagers'; ages 14, 12, 11; a mental-health user who can't work) — lead with a student / low-income price in those markets.")
ext("C027", " Report 31: 61 localisation requests (1.18%) and French and German reviewers say localisation is their purchase condition ('J'achèterai la version premium quand elle sera traduite en français'; didn't buy Pro because there was no German); China is the happiest storefront (4.09) and the loudest localisation demand (23.9% — '无中文无满分', no Chinese, no full marks); Ukraine 26.7%, Russia 13.6%, France 11.3%; recommended: Spanish, Portuguese, Chinese, German, French, Russian.")
ext("C029", " Report 31: billing-dispute language in 403 reviews (7.77%, mean 1.24) — refund, scam, fraud, estafa, arnaque, Abzocke, 欺诈 in eight languages — with 13 calling on Apple to remove the developer; billing & entitlement integrity rose 1.6% (E1) → 34.5% (E4) → 25.4% (E5): 768 reviews (14.81%, mean 1.30); discount offers checked out at full price in 69 (49 actually charged; '$59.99 crossed out and … $9.99 … My card was charged full price'; support: 'a bug that happens sometimes') — make the displayed price the charged price and audit introductory-offer configuration per storefront (CA, AU, GB, DE first).")
ext("C030", " Report 31: sync / backup / restore fails in 83 reviews ('Manual syncing is so 2010'); real-time iCloud sync across iPhone, iPad and Watch is requested with the iPad layout, concentrated in the 4★ band.")
ext("C031", " Report 31: the app would not open in 1,052 reviews (20.29%, mean 1.30) in five waves — launch season 2016, intro freeze Oct–Dec 2021, v1.19.0 crash on launch 22 Dec 2021 → ~8 Jan 2022 (918 in the window), a post-update white-screen hang May–Jun 2022, freezes after subscribing 2022–23; devices from iPhone 6 to 12 Pro Max, so not an old-device issue; 1★ in E3 is 66.4% launch failures; the fix did not recur at scale.")
ext("C032", " Report 31: v1.19.0 shipped a crash on launch on 22 Dec 2021, into the New Year and a TikTok-driven install surge — 1,135 reviews in 25 days (21.89% of the corpus, 79.4% 1★, 51% non-US), 35% of lifetime 1★; 47 reviewers never got to use the app; collateral data loss ('Lost more than 2 years of data'); the 2022 mean of 1.74 is a release-engineering outcome — stage rollouts and freeze releases before acquisition or seasonal peaks.")
ext("C033", " Report 31: 468 reviews (9.02%, mean 1.23; 304 explicit payers) say Premium they paid for was not granted — 2023 200, 2024 200 — including 295 'lifetime' buyers who stayed on Basic (mean 1.14, 89.5% 1★): the post-purchase 'gift' / Growth-Bundle screen appears to drop the entitlement when dismissed ('by not finishing this flow and purchasing the upsell, I think it doesn't recognize I purchased it'); one clean success ('I was successful at purchasing and using a lifetime premium upgrade') suggests a code-path defect that ran at least 16 months — make the entitlement grant atomic with the purchase and show any cross-sell after.")
ext("C034", " Report 31: data / streaks lost or reset in 94 reviews (a 109-day no-wine streak; sobriety 40 → 16 days; 200+ day streaks to 0); counts corrupted by v2.7.1/2.7.2 in 107 (58,720 — 'Do not download 2.7.2!!!'); a habit tracker's only durable asset is the user's history, which users treat as health data — gate releases on data-migration tests and stage every rollout.")
ext("C036", " Report 31: 460 reviews (8.87%, mean 1.32) say support never replied or the contact path was broken (dead typeform links, a Mail-app-only link), rising 0.6% (E1) → 20.3% (E4) → 20.8% (E5); in E1 support was praised (11 of 18 support-praise reviews) — staff a single working contact path with a published response time and resolve by receipt, not by argument.")
ext("C038", " Report 31: time-zone travel rewrote 600- and 1,500-day streaks (13); the week-start setting was ignored and weeks reset on Sunday, including in widgets (30; a 3-year premium user 'begging'); store completions against the local calendar day, not a UTC timestamp.")
ext("C040", " Report 31: widget mentions 195 (3.76%) — positive in E1, demand in E2, complaint after the Oct 2021 downgrade; the widget ignored the week-start setting.")
ext("C042", " Report 31: ADHD / autism / OCD users 33 (mean 4.09 — 'every other app overcomplicates… this app is BEAUTIFUL and simple'), medication and body-care tracking 36 (3.42), mental-health context 38; coaches, clinicians and therapists recommend it — they are the most loyal and the most hurt by regressions (monthly frequency, streak display, medication streaks).")
ext("C043", " Report 31: 'N times per period' with no fixed days is praised by 81 (a monthly view prevents 'feel bad' spirals); removing monthly and yearly frequencies (Dec 2022 – Jan 2023) drew 58 requests still arriving in 2026 ('This was the ONE reason I used to love this app'; contact lenses monthly, weight loss yearly; 'call friend once a month or take a vacation three times a year'; deep-clean the oven monthly).")
ext("C044", " Report 31: iPad / Mac / landscape / web / Android wanted by 98 (1.89%, mean 3.49), peaking in the 4★ band (7.5%) and in E1 (5.3%), falling to ~1% after 2021 as those users left.")
ext("C045", " Report 31: groups/categories (added Mar 2018) were paid and valued by buyers; forced daily/weekly grouping and order resets in v3.0 (22) drew complaints.")
ext("C046", " Report 31: Siri Shortcuts were removed in the Mar 2022 rebuild and automations broke (14).")
ext("C048", " Report 31: unit tracking with custom increments (dollar amounts for business referrals) is praised; a custom-count input bug added an extra unit ('I type in 50 pages … it counts 55', 16).")
ext("C050", " Report 31: one-off tasks / today-only items requested by 28 (mean 2.86).")
ext("C051", " Report 31: Android and web appear in the 98 platform requests.")
ext("C059", " Report 31: the original solo developer shipped a wished-for feature two days later, replied to a crash e-mail and fixed it 'ASAP', restored a purchase 'within minutes' — support praise 18 (mean 4.78), 11 in E1; after the sale, public developer replies began only in 2024 with split outcomes (restored within days vs a promised refund never issued, 'they sneakily changed their developer response') and support-unresponsive stayed at 20.8% in E5.")
ext("C060", " Report 31 (counter-evidence): the Growth Bundle cross-sell became the only upgrade path and a post-purchase 'gift' upsell that broke entitlements — 36 bundle complaints (mean 2.03).")
ext("C061", " Report 31: 'supporting a small team' was an E1 purchase trigger ('there is a small team behind so I was happy to pay'; 'happy to support the designers').")
ext("C062", " Report 31: high-spend storefronts (78.0%) and the rest of world are almost identical on sentiment (2.34 vs 2.42) but high-spend reports the money story (1.9× cap, 1.4× friction, 1.9× support-unresponsive) and the rest of world the crash wave and language (3.3× localisation); the tail of 71 small storefronts rates better (2.58) than the 9 core ones (2.30) — the more reviewers engaged with paying, the worse the rating.")
ext("C063", " Report 31: trial reaction is net-negative (56, mean 2.16) and the positive outcomes are first-year discount trials, not free trials ('an almost-free year is more than enough to know whether the €60 is worth it').")
ext("C064", " Report 31: 'a subscription for a checklist is unjustifiable' ('almost the price of Disney+!'; 'In this economy?'; 'How is this app worth $499.99?') — price objection 379 (7.31%, mean 1.79), 4.1% (E1) → 13.0% (E2); Canada has the highest price objection (11.6%); do not conclude 'lower the price' alone — restore a trustworthy low-commitment path and make it work.")
ext("C065", " Report 31: explicit payers went from the happiest segment (E1 mean 3.76) to the angriest (E4 1.35) while their share of reviews rose six-fold to 25.0%; 17.2% of 1★ reviews are from people who say they paid; within 625 payers: not granted 48.6% (1.21), support unresponsive 34.2%, still upsold 31.5%, lag 13.3% ($79.99, freezes on the third habit); a share bought only to make the pop-up go away.")
ext("C067", " Report 31: health and medical routines praised by 36 (hip-surgery physio, Ménière's, a 95-day medication streak); life outcomes 113 (34 kg, 15 lb).")
ext("C068", " Report 31: family/child use praised by a handful — a parent tracking attention to each child; a 5-year-old's morning list.")
ext("C069", " Report 31: musical completion sounds and haptics are free and part of the category-winning basics (82 mentions, mean 3.62); 7 find sounds interrupt audio.")
ext("C071", " Report 31: after a Dec 2020 sale ('sold from Tree Betty to this new owner') the new operator went silent on support and legacy purchases while escalating monetisation — 'ever since the original designer/developer sold it … it's stopped working'.")
ext("C072", " Report 31: Apple Health counts wrong or doubled in 37 (2.7.1 added a year of steps; sleep 14 h; 26,000 vs 5,000 steps) — de-duplicate imports and show the source value alongside the app's value.")
ext("C073", " Report 31: custom order and forced grouping (22) and an edited habit jumping to the top of the list drew complaints — restore custom ordering and stop moving edited habits.")
ext("C080", " Report 31: dark mode / themes 18; a German visually impaired reviewer: 'no accessibility features, no dark mode, no localisation … unusable'.")
ext("C083", " Report 31: freeze / lag 404 (7.79%, mean 1.62) rising in every era to 26.6% of 2025–26 — '10 seconds for the sound effect, another 20 seconds for the colour to change'; '20-30 seconds per habit'; 'it now takes several seconds to add a single entry … can't cope with too many entries' (iPhone 15 Pro) — set a tap-to-register budget (<100 ms) and test with multi-year histories; some reviewers infer throttling of non-subscribers (untested).")
ext("C089", " Report 31: '83–90% off' first-year offers ($8.99–$9.99) checked out at $59.99–$99.99 through 2022–23, and a $19.99 'lifetime' was shown against anchors of $399–CA$499.99 that charged without unlocking.")
ext("C093", " Report 31: upsell nag 676 (13.04%, mean 1.72) rising 1.9% (E1) → 22.6% (E4) through a full-screen offer on every launch (2021), a permanent 'Just for you' list cell (2023) and two pop-ups per launch (2024, mean 1.47) — 'the only habit I'm developing is closing the upsell pop up'; a share of E4 purchases were made 'to get rid of the incessant pestering', and when relief did not arrive they produced the angriest reviews; E1 buyers valued 'that they don't prompt you to update every 3 clicks'; cap offers at one dismissible surface per week.")
ext("C094", " Report 31: no review-prompt inflation — 20 prompt complaints (0.39%) and short reviews ≤7.7% of every era; about 1–2% of 5★ are complaints rated 5 'so people see it'.")
ext("C101", " Report 31: celebration on completion requested by 44 (mean 3.98), while achievements/trophies added in Apr 2023 were unwanted by long-time users.")
ext("C103", " Report 31: sobriety, medication and mood-disorder trackers were hit by streak resets, removed quit-to-zero goals and upsells interrupting tracking.")
ext("C104", " Report 31: monthly/yearly frequency, streak display, swipe, quit-to-zero, Shortcuts, the tappable widget, 'last done' and day-start time were removed across v2 (Mar 2022) and v3.0 (27 Jan 2023) — feature removal 9.4% of E4, an update blamed for a regression 8.4%; the legacy Premium stopped being recognised in Apr 2023 with no notice.")
ext("C109", " Report 31: a 'free trial' that was actually a paid first year ('told I would be getting one year, 365 days free … now only … a month'), a trial renewing into the most expensive plan, and a trial not visible in iOS subscriptions.")
ext("C112", " Report 31: 66 cannot cancel / charged after cancelling (mean 1.39, mostly E4) — no subscription found in iOS Settings; 'cancelled … TWICE and I'm still being charged'; put 'Manage subscription' in the app.")
ext("C113", " Report 31: reviewers quote 60+ price points across 15 currencies; a 'Christmas' $11.99 → $39.99, perpetual 72-hour countdowns that reset, 83–90% off banners and $399 anchors — and 69 say the advertised price was not the charged price.")
ext("C127", " Report 31: the promotional banner hid a habit even for paid users (Dec 2020).")
ext("C133", " Report 31: the cap stayed fixed while packaging changed; buyers valued unlimited habits, reminders, charts, groups and export.")
ext("C134", " Report 31: lead with simplicity, colourful friendly design, build + quit in one list, 'N times per week' and musical sounds — 458 simplicity and 250 design praise reviews prove the brief.")
ext("C141", " Report 31: native iPad layout with landscape named as the 4★ → 5★ condition ('I will gladly give 5 stars'); Malaysia 21% platform requests.")
ext("C142", " Report 31: misunderstandings about how to edit or delete a habit, what 'untracked' means, what colours and X/O marks mean and how 'quit' goals count — a UX problem, not a gap.")
ext("C145", " Report 31: a 'Self-care Christmas' banner hid the bottom habit; a permanent 'Just for you' list cell slowed scrolling and tapping — never let a promotional element occupy a habit row or slow the list.")
ext("C147", " Report 31: 'Free is useless, paid is too expensive to try' — the evaluation argument is the plurality monetisation objection since 2016; 'Tried the 3 free habits and wanted more' was an E1 purchase trigger when the unlock was a $4–9 one-off.")
ext("C155", " Report 31: 'The app gets prettier. The actual functionality gets worse. Every time.' — removed monthly/yearly frequency (58), streak on the main list (52, partly restored then removed again), swipe between days (41); 'That is one of the biggest reasons I paid' (feature removed after paying, 21); a minority liked the redesigns.")
ext("C156", " Report 31: 1.19.0 (launch crash), the May 2022 hang and 2.7.1/2.7.2 (count corruption) were all shipped to everyone.")
ext("C163", " Report 31: a monthly billing plan was wanted (8) and one user had to switch to monthly to be able to cancel before a €100+ renewal.")
ext("C170", " Report 31: a day-start offset for late sleepers and shift workers (capped at 5 am) was later removed; day-start / midnight rollover 18.")
ext("C171", " Report 31: no VoiceOver support, small fonts/buttons (19) — ship VoiceOver labels, Dynamic Type and 44 pt targets.")
ext("C172", " Report 31: notes/journal per entry and timestamps (added Jan 2017) — 82 mentions (mean 3.52); 'last done / minutes ago' removed in 2022–23.")
ext("C175", " Report 31: v2 rebuild (Mar 2022) brought 10–30 s tap lag, a broken Watch app and removed past-entry editing (restored in 2.0.8); v3.0 (Jan 2023) brought a week-start bug and a custom-count +1 bug.")
ext("C178", " Report 31: the simple, colourful adult tracker is loved consistently in every era, and contrasted with Habit-Bull's 'roided-out CrossFit guy'.")
ext("C180", " Report 31: countdowns that reset — 111 reviews (2.14%) — '72 hour countdown and reset back to 72 hrs'; 'like the DFS adverts, constantly on sale'; 'ran for months'; 'I'm pretty sure this type of fake sale is actually illegal'; fake urgency backfires in a self-improvement category.")
ext("C186", " Report 31: 189 legacy one-time / lifetime buyers (mean 1.38) found their purchase shown as 'Done Basic' after an update, reinstall or new phone, beginning at the Dec 2020 ownership change and spiking Apr 2023 — support 'told me they wouldn't honour my previous purchase', offered a free trial, or removed 'grandfathered access'; one wrote the top 'Done app review' article and then a 1★; validate receipts for every historical SKU and grandfather them automatically — worth more than any feature.")
ext("C189", " Report 31: a support reply 'full of emojis' offered a free trial instead of honouring a purchase; a public developer response was edited after the fact.")
ext("C196", " Report 31: 'a subscription for a checklist is unjustifiable' — the subscription came with removals, lag and no visible new delivery.")
ext("C214", " Report 31: 'How is this app worth $499.99?'; '$90/pY for what?' — simplicity is quoted both as the reason to use the app and the reason a subscription is unjustified.")
ext("C218", " Report 31: 57 say the price was hidden or the listing implied 'free' ('needs an in-app purchases mark'; 'online ads … said it was under $10 one time'); 50 describe an intro price renewing much higher only 'in the small print' (9.99€ → 100.99€; £5.99 → £51.99, 'just hoping someone doesn't cancel').")
ext("C219", " Report 31: a minority reported 2 or 4–5 free slots after deleting and re-adding, which the free tier did not always allow.")
ext("C221", " Report 31: show the renewal price before purchase — 50 renewal shocks (mean 1.44).")
ext("C231", " Report 31: Australia shows the monetisation and integrity story without the crash wave (friction 43.5%, entitlement 14.0%, billing 19.7%, launch 9.3%); Canada is the worst large storefront (2.10, 57.7% 1★); Brazil and Mexico are wave-dominated (launch 28.6% / 28.1%, upsell only 2.2% / 3.5%); Switzerland was offered 10 CHF and charged 59 CHF; Hong Kong and India show 26.7% / 17.1% entitlement failure.")
ext("C234", " Report 31: statistics (145 mentions) and charts were a paid unlock and a purchase trigger in the one-time era.")
ext("C238", " Report 31: teens blocked by the cap and price in the 2022–23 TikTok cohort — a student / low-income price is the report's answer.")
ext("C058", " Report 31: TikTok / Instagram / YouTube / press named by 117 (mean 1.72), 81 of 98 TikTok mentions in 2022 — the channel that brought the largest audience arrived during a launch crash.")

